2, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227205.html', '2026-04-15T07:05:55.989036');
