INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229250, 1282780, 'Empleada doméstica General Pacheco (Sábados y Domingos)', 'Adecco - Permanent Talent', 'BUSCAMOS TALENTOS, ¡EN ADECCO TE ESTAMOS BUSCANDO!Si te interesa desarrollarte como Empleada Doméstica en General Pacheco en el equipo de nuestro cliente IMPORTANTE EMPRESA ¡desafíate a vos mismo y crea tu futuro!¿Qué tareas vas a realizar? Limpieza general de todos los ambientes. Orden y mantenimiento de espacios comunes. Gestión de residuos y reposición de insumos básicos. Comunicación y aviso de necesidades de mantenimiento.¿Qué valoramos de tu perfil? Experiencia previa en tareas de limpieza o mantenimiento. Conocimiento en el uso seguro de productos de limpieza. Puntualidad, compromiso y responsabilidad. Capacidad para organizar tareas y trabajar de manera autónoma.¿Qué ofrecemos? Jornada: disponibilidad full time para sábados y domingos. Lugar de trabajo: Talar del Lago – General Pacheco.Somos Adecco Argentina, una compañía con más de 30 años conectando talento con oportunidades y brindando soluciones integrales en Recursos Humanos. Buscamos personas como vos, que quieran seguir creciendo. Nuestro compromiso es la diversidad y la igualdad de oportunidades. Somos una empresa inclusiva: en nuestros procesos solo evaluamos tus méritos, logros y capacidades. Participar no tiene ningún costo para vos; acompañarte es parte de nuestra tarea con la comunidad. El empleador solo podrá solicitarte la información estrictamente necesaria para el desempeño del puesto. Ciudad de Buenos Aires – Ley 6471 de búsqueda laboral equitativa. ¡Postulate y animate a dar el próximo paso en tu carrera!', 0, 'General Pacheco, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 13:19:00', '13-04-2026 14:40:07', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2609, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/2/8/2/7/8/0/logoMainPic_1282780_bum_vf37880d6.jpg', 0, 0, 3.73, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229250.html', '2026-04-15T07:05:55.989811');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118231433, 268500, 'JEFE / SUPERVISOR DE VENTAS', 'Ofishop', 'Responsabilidades Supervisión diaria de ejecutivos/as de cuenta en home office. Seguimiento de ventas de insumos de oficina a empresas. Cumplimiento de objetivos comerciales y análisis de resultados. Coaching, acompañamiento y motivación del equipo. Reportes de gestión y coordinación comercial.Requisitos Experiencia como Jefe/a o Supervisor/a de Ventas (excluyente). Experiencia en venta de insumos de oficina o productos B2B similares. Liderazgo de equipos comerciales remotos. Excelente comunicación, empatía y habilidades interpersonales. Manejo de Excel y herramientas comerciales (CRM).Se ofrece Trabajo remoto. Equipo de ventas activo. Remuneración acorde + incentivos por resultados.', 0, 'Capital Federal, Buenos Aires', 'Remoto', 'Full-time', '14-04-2026', '14-04-2026 15:35:50', '14-04-2026 15:59:17', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/0/2/6/8/5/0/0/logoMainPic_268500.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118231433.html', '2026-04-15T07:05:55.989876');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230655, 13398676, 'ENCARGADO/SUPERVISOR DE REPARTO', 'Distribuidora Correa', 'TE ESTAMOS BUSCANDO Somos una empresa embotelladora y distribuidora de agua y soda de la ciudad de BERNAL.Nuestro principal objetivo es cumplir con la necesidad de grandes empresas, pymes y casas de familia en tiempo y forma, con productos de mejor calidad y precio.En esta oportunidad, estamos buscando incorporar a nuestro staff un ENCARGADO DE REPARTOSe valorará tener experiencia en manejo de camiones, buen trato con clientes y residir cerca de la zona.Tareas: Reparto de bidones de agua y soda en camión asignado Manejo de camión (similar a Mercedes 710, IVECO, etc.) Atención directa a clientes y buena comunicación Manejo de dinero (cobros y rendiciones) Confeccion de remitos y recibos de cobros Control y entrega de mercadería Organización y cumplimiento de recorridos Reportes a la gerenciaSe requiere: Experiencia comprobable como chofer de camión y/o utilitario (excluyente) Licencia de conducir vigente (excluyente) Experiencia en reparto y trato con clientes Experiencia en manejo de dinero y cobranzas Responsabilidad, puntualidad y compromiso Ganas de crecerTe ofrecemos:Trabajo estable. No es por contrato.Sueldo competitivo con posibilidades de crecimiento + Comisiones por venta.Se valorara especialmente: Perfil comercial / ventas Experiencia en reparto de agua, bebidas o productos similares Conocimiento de Zona Sur Referencias laborales comprobables Iniciativa y proactividadInicialmente el chofer comenzara a trabajar como ayudante para tomar conocimiento con la dinámica del trabajo, reparto, hoja de ruta y clientes.De Lunes a Sabado.Excluyente (si no cumple con estos requisitos no se postule)-Edad de 21 años a 49 años.-Registro de conducir vigente.-Remuneración Pretendida.INCORPORACION INMEDIATA.', 0, 'Bernal, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 10:46:46', '14-04-2026 10:58:45', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 2, 0, 3, 54, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13398676_bum_v3e660320.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230655.html', '2026-04-15T07:05:55.989969');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230684, 568160, 'Lider de Proyecto', 'OPTARIS S.A.', 'Optaris nace como empresa de software para crear soluciones innovadoras focalizadas en el mercado latinoamericano, nos motiva el uso de nuevas tecnologías para la creación de soluciones que ayuden a nuestros clientes a tener mejor visibilidad de sus negocios y mayor escala:Nuestra pasión es la tecnología y nuestro compromiso es con el cliente, centrando al usuario de negocio en el centro de la escena para ofrecerle tecnologías revolucionarias a bajo costo. Liderar la planificación, ejecución y seguimiento de proyectos tecnológicos, asegurando la entrega a tiempo, dentro del presupuesto y con la calidad esperada. Coordinar y supervisar las actividades de equipos de Especialistas de Aplicaciones y Desarrolladores IT, garantizando la alineación con los objetivos del proyecto y del negocio. Colaborar con clientes internos y externos para identificar requerimientos, proponer soluciones innovadoras y alinear expectativas. Diseñar estrategias para maximizar el uso de plataformas de low-code / no-code y soluciones empresariales integradas. Realizar presentaciones y demos de avances y resultados a stakeholders clave. Promover la adopción de metodologías ágiles y asegurar la implementación de mejores prácticas en el ciclo de vida del proyecto. Identificar oportunidades de mejora continua y potenciar el desarrollo profesional de los miembros del equipo. Requisitos: Título universitario en Sistemas de Información, Ingeniería en Sistemas, Administración de Empresas, Ingeniería Industrial u otras carreras afines. Más de 5 años de experiencia en liderazgo de proyectos de TI, especialmente en contextos que involucren sistemas empresariales como ERP, CRM, o soluciones basadas en plataformas low-code / no-code. Conocimientos técnicos en plataformas de desarrollo de aplicaciones de bajo codigo y arquitecturas empresariales modernas (Cloud, APIs). Certificaciones en gestión de proyectos, como PMP, Scrum Master, o Agile Coach, son altamente valoradas. Experiencia en metodologías ágiles y herramientas de gestión (Jira, Trello, Azure DevOps). Capacidad para coordinar equipos interdisciplinarios, incluyendo desarrolladores IT, especialistas en aplicaciones y analistas funcionales. Habilidades avanzadas en análisis funcional y diseño de soluciones. Valoramos una mentalidad "Hands-on" Nivel avanzado de inglés para interactuar con stakeholders internacionales. Valoramos perfiles que residen en Buenos Aires . Beneficios Ser parte de un entorno dinámico, colaborativo y en constante innovación. Participar en proyectos de alto impacto para clientes nacionales e internacionales. Modalidad 100% remota, con horarios flexibles. Planes de capacitación y certificaciones para potenciar tu crecimiento profesional. Oportunidad de liderar un equipo talentoso y de alto rendimiento, con acceso a tecnologías y herramientas de vanguardia. Reintegros en clases de Ingles. Bienestar: Reintegros en clases de actividad fisica a eleccion.', 0, 'La Plata, Buenos Aires', 'Remoto', 'Full-time', '14-04-2026', '14-04-2026 10:56:24', '14-04-2026 10:56:24', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 2, 0, 19, 2619, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230684.html', '2026-04-15T07:05:55.990085');
