5:55.991202');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229487, 13511179, 'Responsable de Logística', 'TDS', 'Responsable de Logística Resumen del Puesto Buscamos un Responsable de Logística para unirse a nuestro equipo. El candidato ideal tendrá experiencia en la gestión de inventarios, depósitos y el control de ingresos y egresos de mercadería. Responsabilidades Control y gestión de inventario. Organización y mantenimiento del depósito. Preparación de pedidos. Coordinación de entregas y despachos de mercadería. Emisión de documentación de transporte. Supervisión de ingresos y egresos de mercadería. Requisitos Experiencia en manejo de autoelevador/montacargas. Licencia de conducir vigente. Experiencia previa en tareas de logística o depósito. Proactividad y responsabilidad. Orden y atención al detalle. Capacidad para trabajar en equipo. Ofrecemos Incorporación inmediata. Buen ambiente laboral. Oportunidades de crecimiento.', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 14:26:03', '13-04-2026 15:45:22', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 3, 29, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229487.html', '2026-04-15T07:05:55.991311');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227118, 13019544, 'Supervisor/a de Taller', 'Vanguardia Consultores RR.HH.', 'Empresa líder en soluciones industriales, especializada en mantenimiento y reparación de equipos de movimiento de materiales, con fuerte foco en la calidad de servicio, la mejora continua y el desarrollo de sus equipos técnicos. Nos encontramos en la búsqueda de un Supervisor de Taller para liderar equipo técnico y garantizar el correcto funcionamiento de las operaciones.Responsabilidades: Coordinación y asistencia de técnicos en taller Gestión de provisión de insumos y repuestos Capacitación del personal en tareas de reparación Control de orden y limpieza del sector Participación en procesos de mejora continua Requisitos: Técnico Mecánico o Electromecánico Experiencia mínima de 3 años (comprobable) Experiencia en autoelevadores (excluyente) Buen manejo de relaciones interpersonales Registro de conducir Manejo de PC / SAP (no excluyente) Beneficios Jornada: lunes a viernes de 8 a 18 hs + sábados de 8 a 13 hs Modalidad: presencial Comedor en planta', 0, 'General Pacheco, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 09:50:34', '13-04-2026 09:50:34', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2581, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13019544_bum_vab558942.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227118.html', '2026-04-15T07:05:55.991421');
