INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226303, 13330439, 'Senior Sales Account Executive', 'WE ARE REMOTERS', 'Find Bandit es una empresa especializada en conectar talento profesional de Latinoamérica con empresas internacionales, principalmente de Estados Unidos, que buscan sumar personas a sus equipos de forma remota.Trabajamos acompañando a los candidatos a lo largo de todo el proceso de selección, con una comunicación clara, cercana y transparente. Nuestro objetivo es que conozcas en profundidad cada oportunidad: el proyecto, el equipo, el tipo de trabajo y las expectativas, para que puedas evaluar si realmente se alinea con tu experiencia y tus objetivos profesionales.En Find Bandit creemos que una buena experiencia comienza con procesos honestos y bien comunicados. Por eso, buscamos generar vínculos de largo plazo, cuidando tanto a las personas como a las empresas con las que trabajamos. Nos interesa que cada incorporación sea una decisión consciente, sostenible y positiva para ambas partes.Si estás buscando un nuevo desafío remoto, trabajar con equipos internacionales y seguir creciendo profesionalmente, en Find Bandit te acompañamos para que encuentres una oportunidad que realmente haga match con vos. About the Role"The company" is currently seeking an experienced and results-driven Senior Sales Account Executive to join our dynamic sales team in our Corporate Sales division.This position requires a background in sales of SAP, Oracle, Microsoft, Salesforce, or other enterprise software solutions.The ideal candidate will be responsible for managing and expanding key client relationships, driving revenue growth, and contributing to the overall success of the sales department within the midsize to large enterprise market.The Senior Sales Account Executive will report to the VP of Sales (Enterprise) and play a pivotal role in developing and executing strategic sales initiatives.Primary Responsibilities Actively prospect new clients and business opportunities in the designated North America region Develop and maintain strong relationships with existing clients, ensuring satisfaction and loyalty Conduct effective presentations, highlighting "The company" North America’s benefits and differentiators, adapting the approach to each client’s specific needs Work closely with "The company" North America and SAP marketing team to develop lead generation strategies and participate in industry events Maintain a deep understanding of the market, identifying opportunities and threats, and adjusting the sales strategy as needed Negotiate contracts and close profitable and sustainable business deals Collaborate with internal teams to ensure the efficient and effective delivery of "The company" North America’s solutions Requisitos: RequirementsSuccess in this position will require initiative, drive, creativity, and adaptability. We are looking for a professional who shares our values and enthusiasm for contributing to the growth and success of "The company" in North America and our customers.Qualifications and Required Skills Proven experience (+5 years) in sales, preferably in the technology or software solutions sector (SAP, Oracle, Microsoft, Salesforce, or Workforce) Exceptional presentation skills, with a captivating and persuasive approach to engage prospective clients Strong sense of urgency to meet dynamic market demands and efficiently close deals Excellent verbal and written communication skills in english. Familiarity with best sales practices and market trends in North AmericaIn addition to the requirements mentioned, we value initiative, creativity, and adaptability. We are looking for a professional who shares our values and is enthusiastic about contributing to the growth and success of "The company" in North America.', 0, 'Buenos Aires', 'Remoto', 'Full-time', '14-04-2026', '14-04-2026 05:02:31', '14-04-2026 05:02:31', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226303.html', '2026-04-15T07:05:55.994865');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225575, NULL, 'Analista de Administracion y Finanzas con exp. en cobranzas, conocimiento contable.', 'Confidencial', 'Importante empresa de logistica ubicada en Capital Federal, incorporara a su equipo de trabajo un Analista que formara parte de equipo de Administracion y Finanzas.La búsqueda está orientada a un estudiante que se encuentre promediando la carrera universitaria o graduado,Principales responsabilidades: Analizar y atender la situación financiera de la empresa en bancos. Experiencia en cobranzas, conocimiento contable. Seguimiento de facturas, emisión de recibos y control de retenciones sufridas. Conciliar cuentas corrientes de clientes, registración de asientos contables, contabilización de facturas. Colaborar en el armado del balance, manejo de la caja y realizar trámites correspondientes del sector.Requisitos:Profesional o estudiante promediando la carrera de Lic. Administración de Empresas o Contador.Contar con al menos dos años de experiencia realizando tareas similares en otras empresas o en estudios contables.Lugar de residencia: Capital Federal - Zonas aledañas a TribunalesConocimientos informáticos: Excel y se valorará conocimiento en el uso de Sistema Tango Gestión.Disponibilidad para trabajar presencial de 08:30 a 18:00. 4 Dias presenciales y 1 home Office', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:06:36', '13-04-2026 14:58:16', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225575.html', '2026-04-15T07:05:55.995012');
