INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224809, 13455277, 'Vendedor/a con experiencia en Planes de Ahorro', 'Paola Escalona', 'Vendedor/a con experiencia en Planes de Ahorro Resumen del PuestoBuscamos Vendedores/as dinámicos y orientados a resultados con experiencia en la venta de planes de ahorro. Si tienes pasión por las ventas, un excelente manejo de las relaciones con los clientes y buscas un entorno de trabajo desafiante y gratificante, ¡esta es tu oportunidad!Responsabilidades Gestionar el proceso de venta de planes de ahorro, desde la captación inicial hasta el cierre de la operación. Realizar el seguimiento de clientes potenciales, brindando asesoramiento personalizado y resolviendo sus inquietudes. Cumplir con los objetivos de venta establecidos, superando las expectativas y contribuyendo al crecimiento del equipo. Mantenerse actualizado sobre las características y beneficios de los planes de ahorro ofrecidos.Requisitos Experiencia comprobable en ventas, preferentemente en el rubro de planes de ahorro. Excelentes habilidades de comunicación y negociación. Orientación al cliente y capacidad para construir relaciones duraderas. Proactividad, dinamismo y capacidad para trabajar en equipo. Conocimiento de herramientas informáticas y CRM.', 0, 'Buenos Aires, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:09:01', '14-04-2026 11:04:50', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224809.html', '2026-04-15T07:05:55.995385');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118232123, 13406073, 'Representante de Ventas con Experiencia en Atención al Cliente', 'Pecanes Argentinos', 'Representante de Ventas con Experiencia en Atención al Cliente Resumen del Puesto Estamos en la búsqueda de profesionales de ventas con una sólida trayectoria en atención al cliente para integrarse a nuestro equipo. Buscamos personas proactivas, con excelente predisposición y capacidad para gestionar relaciones con los clientes de manera efectiva. Responsabilidades Atender y asesorar a los clientes, comprendiendo sus necesidades. Gestionar y mantener la base de datos de clientes utilizando herramientas CRM. Colaborar en la consecución de los objetivos de venta. Proporcionar un servicio de post-venta de calidad. Mantener un registro detallado de las interacciones con los clientes. Requisitos Experiencia comprobable en roles de ventas y atención al cliente. Dominio de herramientas de gestión de relaciones con clientes (CRM). Conocimientos sólidos en el uso de software de hoja de cálculo (ej. Excel). Excelentes habilidades de comunicación, interpersonales y de negociación. Actitud positiva y orientada a la resolución de problemas. Capacidad para trabajar de forma autónoma y en equipo.', 0, 'Caseros, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 20:11:34', '14-04-2026 20:13:54', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118232123.html', '2026-04-15T07:05:55.995506');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230033, 13450185, 'Vendedor/a con Experiencia (valoramos perfiles +50)', 'Escuela de Manejo Defensivo Rtw', 'Vendedor/a con Experiencia (valoramos perfiles + 5 0)Resumen del PuestoBuscamos un/a Vendedor/a con experiencia comprobada en el trato con clientes, enfocado/a en resultados y con un sólido criterio comercial. Valoramos especialmente a aquellos/as con trayectoria, compromiso y la habilidad para generar confianza en el cliente.Responsabilidades Contacto con potenciales clientes. Seguimiento y cierre de operaciones comerciales. Asesoramiento personalizado a clientes. Gestión de consultas y oportunidades comerciales.Requisitos Experiencia previa en ventas (excluyente). Habilidades de comunicación y cierre comercial. Perfil autónomo, responsable y constante. Capacidad para asesorar al cliente de manera efectiva. Se valorará la experiencia y el deseo de mantenerse activo/a comercialmente.Ofrecemos Trabajo con un servicio de alto valor. Flexibilidad y autonomía en la gestión. Oportunidades de crecimiento profesional. Un excelente ambiente de trabajo.', 0, 'General Rodríguez, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 14:36:06', '14-04-2026 15:11:55', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230033.html', '2026-04-15T07:05:55.995626');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229753, NULL, 'TECNICO en MANTENIMIENTO INDUSTRIAL con Experiencia Comprobable', 'Confidencial', 'Laboratorio de Cosmética Capilar en GBA Oeste (Ciudadela) se encuentra en la búsqueda de TECNICOS en MANTENIMIENTO INDUSTRIAL.La búsqueda se encuentra orientada a:TÉCNICO MECÁNICO EXPERTO EN MAQUINARIAS: Experiencia comprobable en ejecución de tareas de mantenimiento preventivo y acciones correctivas, reparaciones de máquinas y sistemas industriales en planta. Experiencia en mecánica general, cambio de motor, motoreductor, rodamientos. Dominio de sistemas mecánicos, eléctricos y neumáticos en máquinas llenadoras, estuchadoras y envasadoras (requisito preponderante). Conocimiento de soldadura inoxidable, MIG y TIG. Capacidad para realizar diagnósticos de fallas y reparaciones en equipos de producción. Familiaridad con la normativa de seguridad industrial y buenas prácticas de mantenimiento. Excelentes habilidades analíticas para resolver problemas técnicos. Capacidad para trabajar en equipo y colaborar eficazmente con otros departamentos (producción, envasado, calidad, etc.). Habilidades de comunicación para reportar incidencias y trabajar con manuales técnicos. Valoralemos conocimiento de PLC y principios de electrónica. (No excluyente). Experiencia en análisis y comparativa de cotizaciones. Manejo básico de Excel, Word, envío y recepción de mails. Experiencia en electricidad monofásica y trifásica. Experiencia en sistemas neumaticos, plomería, etcNuestra busqueda está orientada a personas muy proactivas, con un perfil dinámico, ordenado, acentuado sentido común, con gran capacidad de análisis, marcada capacidad resolutiva, analítica, con orientación al resultado y excelente predisposición para el trabajo en equipo.Horario de trabajo: de lunes a viernes de 11:45 a 21:00 hsValoraremos a aquellos postulantes que puedan avalar su experiencia en tareas similares a través de una carta de recomendación.Se dará preferencia a postulantes con experiencia en el rubro cosmética, y que residan en zonas cercanas a Ciudadela, cuenten con practicidad de transporte público para movilizarse a Ciudadela o cuenten con movilidad propia. (No excluyente).Salario a convenir.', 1, 'Ciudadela, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 16:22:20', '13-04-2026 16:22:20', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229753.html', '2026-04-15T07:05:55.995731');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226465, 13062999, 'OFICIAL DE EXPERIENCIA TELEFÓNICA PRESTADORES -Sunchales', 'Sancor Salud', '¿Qué ofrecemos para tu #Bienestar? Trabajo mixto, desde casa y desde la oficina ( de acuerdo a la posición) Días hábiles de vacaciones Día de cumpleaños libre y reconocimientos por antigüedad Días Festivos (24 y 31 Diciembre, Jueves Santo) + días de trámites + Fiestas Patronales UNI: Nuestra Universidad Corporativa te hace protagonista de tu desarrollo! Descuentos en idiomas y universidades Club SanCor Salud Eventos y Sorpresas en días de la familia Programa MADRINAS Descuentos en Nuestras Farmacias | Turismo | Óptica Plan de Salud para vos y tu familia Privilege: Programa de Beneficios exclusivos para colaboradores‍️ Pausas activas, meditaciones y muchos !Estamos orgullosos de poder decir que somos ¡un gran lugar para trabajar!¡Te esperamos!#EstoyDondeQuieroEstar #TuMejorVersión #EstoyDondeQuieroEstar Nos encontramos en la búsqueda de OFICIAL DE EXPERIENCIA TELEFÓNICA PRESTADORES para sumarse a un gran equipo en constante crecimiento y desafíos:Algunas de sus tareas serán: Responder y gestionar consultas y reclamos de acuerdo a los procedimientos y procesos de la compañía Llevar registros en las diferentes herramientas y plataformas Colaborar en el desarrollo de funcionalidades para los activos digitales que maneja el área.La búsqueda se encuentra orientada a personas comprometidas, proactivas, dinámicas y con gran vocación de servicio al cliente. Te contamos además, que el puesto requiere de capacidad de aprendizaje para incorporar rápidamente las metodologías de trabajo, que ya están establecidas bajo normas de calidad. Si te identificas con estas cualidades, te gustan los desafíos, trabajar en equipo y participar de equipos interdisciplinarios: ES TU OPORTUNIDAD!Queremos que acá seas #TuMejorVersión Requisitos: Experiencia en atención al cliente (excluyente) Conocimientos/experiencia en el rubro salud (deseable) Secundario completo (excluyente) Disponibilidad horaria full time Residir en Sunchales (excluyente)', 0, 'Sunchales, Santa Fe', 'Remoto', 'Full-time', '10-04-2026', '10-04-2026 08:58:41', '10-04-2026 08:58:41', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 25, 110, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13062999_bum_vaf7bbda6.jpg', 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/sancor-salud', 'https://www.bumeran.com.ar/empleos/1118226465.html', '2026-04-15T07:05:55.995847');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224707, 2514930, 'Supervisor General para Fabrica de Cerraduras', 'Fratelli Currao S.R.L.', 'Como Supervisor General para Fábrica de Cerraduras, serás responsable de coordinar y supervisar las operaciones diarias de fabricación para garantizar la calidad y eficiencia en los procesos productivos. Entre tus tareas principales se incluyen gestionar el equipo de trabajo, supervisar los estándares de producción y seguridad, y reportar los resultados operativos a la gerencia. Este puesto es presencial, con sede principal en Lomas del Mirador.Requisitos Solidos conocimientos en procesos en balancines, armado y matriceria. Capacidad para liderar equipos y gestionar recursos humanos en un entorno de producción. Habilidades organizativas, planificación de tareas y cumplimiento de plazos de entrega. Actitud proactiva, habilidades de resolución de problemas y capacidad para trabajar en un entorno dinámico. Se valorara uso intermedio o avanzado de herramientas como Excel y sistemas de gestión.Se ofrece Interesantes condiciones de contratacion acordes al mercado.', 0, 'Lomas del Mirador, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:03:13', '13-04-2026 10:10:36', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224707.html', '2026-04-15T07:05:55.995957');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227492, 13339475, 'Analista de Facturación', 'IRSA Inversiones y Representaciones S.A.', 'Somos IRSA. Desde 1943 nos apasiona buscar algo nuevo -justo ahí- donde parecería no haber nada. Convertimos espacios urbanos en lugares llenos de experiencias para vivir y disfrutar. Porque desafiamos los límites de lo obvio, para encontrar eso que creemos que será algo mejor. Somos la empresa más grande de Argentina en bienes raíces porque sabemos escuchar y aprender de nuestros errores y también porque trabajamos duro para convertir todo lo que soñamos en algo concreto. Nos animamos a imaginar y nos arremangamos porque también disfrutamos el desafío. Cotizamos en la bolsa de mercados argentinos (BYMA) y en la bolsa de comercio de Nueva York (NYSE) porque sabemos proyectar sobre lo que existe y contagiar el optimismo de nuestra visión en los siguientes servicios: La adquisición, desarrollo y explotación de centros comerciales; La adquisición y desarrollo de edificios de oficinas y otras propiedades que no constituyen centros comerciales, principalmente con fines de locación; El desarrollo y venta de propiedades residenciales; la adquisición y explotación de hoteles de lujo;La adquisición de reservas de tierras sin desarrollar para su futuro desarrollo o venta;Inversiones selectivas fuera de la Argentina. Además tenemos una participación del 29,91% en Banco Hipotecario (Banco Hipotecario), una de las principales entidades financieras del país.Conocé más en nuestra página web: ¡Nos encontramos en la busqueda de Analista de Facturacion para el equipo de Administración del Centro de Servicios Compartidos de IRSA CRESUD!Sus principales tareas serán: Ingreso de liquidaciones Liquidación, Facturación y análisis de contratos de locación Análisis de Cuentas Corrientes Recopilación Ventas locatarios Requisitos: Gradudo/a o estudiante próximo/a a recibirse de Carreras de Cs. Económicas Experiencia de 2 años en roles similares (o tareas administrativas) Dominio de Excel (excluyente) Manejo de SAP (deseable) Perfil analítico, proactivo, con muy buena comunicación y manejo de las relaciones interpersonales Beneficios Medicina prepaga (Swiss Medical) para vos y tu grupo familiar Bono anual por objetivos Almuerzo, desayuno y refrigerio‍ Programa de Becas - ¡Te acompañamos en tu desarrollo! Reintegro por guardería Licencias especiales Descuentos corporativos en gimnasios, clases de idiomas y hoteles Descuentos en electrodomésticos, productos Bimbo y planes Movistar Descuentos vía ¡appa! en nuestros Shoppings Obsequios para fechas especiales y eventos en vacaciones de invierno‍️ Espacio de relajación y juegos en la oficina‍Esquema de trabajo híbrido¡Sumate a nuestro equipo!', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '14-04-2026', '14-04-2026 05:02:33', '14-04-2026 05:02:33', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2643, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227492.html', '2026-04-15T07:05:55.996161');
