INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223696, 13187218, 'Senior Fullstack NextJS Vercel langchain', 'CONSULTORA ACTIF RH', 'ACTIF Talentxpert te acercamos nuevas oportunidades para tu desarrollo profesional!!! Te presentamos una nueva posición para que puedas aplicar! TalentXperts es nuestra unidad de negocios orientada a Profesionales de distintas partes del mundo, con ganas de insertarse en proyectos innovadores y disruptivos! Esperamos tu postulación y que disfrutes junto a nosotros y nuestro partner este camino! Desde ACTIF buscamos para nuestro cliente Tecnom, un Fullstack Senior con mentalidad de producto e interés en proyectos de innovación y potencial de liderazgo.Tecnom desarrolla soluciones que integran web e inteligencia artificial, como Nubux CRM (digitalización de ventas y postventa en concesionarias) y Tecna Agente AI (clasificación inteligente de leads con automatización y modelos de lenguaje).Tu rol será participar en todo el ciclo de desarrollo end-to end: desde la arquitectura y el frontend hasta el backend y el deploy en Vercel. Requisitos: Queremos alguien con experiencia participando en todo el ciclo de desarrollo: desde el diseño de la arquitectura hasta el deploy. Que disfrute de crear interfaces con aplicando SSR, ISR y Server Components, diseñar y consumir APIs REST, y llevar proyectos a producción en Vercel u otras plataformas como AWS o Netlify. Valoramos además la capacidad de aportar ideas innovadoras y de acompañar técnicamente a developers de menor seniority. Beneficios Trabajo 100% remoto de lunes a viernes (9 a 18 hs) o hibrido en Caba. 5 días libres extra al año + día de cumpleaños + licencias extendidas. Clases de inglés, mentoring y coaching. Almuerzos In Company, Conectividad y herramientas de trabajo cubiertas. Cobertura médica OSDE 210 para el colaborador. Cultura colaborativa, autonomía real e impacto directo en productos usados por miles de usuarios. Sumate a un equipo que apuesta por la innovación y el aprendizaje continuo.', 0, NULL, 'Remoto', 'Full-time', '08-04-2026', '08-04-2026 14:39:42', '08-04-2026 14:39:42', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 2, 0, 19, 34, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223696.html', '2026-04-15T07:05:55.999369');
