ic_13406034_bum_v39597a9d.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118232168.html', '2026-04-15T07:05:56.000296');
