L, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13474992_bum_vce1480a5.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226663.html', '2026-04-15T07:05:56.000372');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228691, NULL, 'SI782 SUPERVISOR DE PRODUCCION | GBA NORTE', 'Confidencial', 'Importante compañía industrial radicada en Zona Norte GBA se encuentra en búsqueda de un/a Supervisor/a de Producción para sumar a su equipo.Objetivo del Puesto: Planificar, coordinar y controlar las actividades vinculadas a los diferentes procesos productivos de planta, asegurando el cumplimiento del programa de producción y la correcta articulación con las áreas operativas involucradas.Responsabilidades: Supervisar y coordinar los procesos productivos de planta para garantizar el cumplimiento del programa de producción. Asegurar el cumplimiento de las normas de calidad, seguridad, higiene y medio ambiente por parte del personal a cargo. Mantener los estándares de orden y limpieza del sector. Verificar el cumplimiento de las formulaciones definidas para cada producto y los estándares de calidad establecidos. Controlar indicadores de eficiencia del sector considerando las capacidades instaladas. Coordinar con el área de Mantenimiento acciones preventivas y correctivas para asegurar el óptimo funcionamiento de los equipos productivos. Gestionar el equipo operativo, detectando necesidades de capacitación y desarrollo en conjunto con Jefatura de Producción y RRHH. Impulsar e implementar proyectos de mejora continua dentro del sector. Coordinar junto al área de Almacén el control de stock de materias primas, insumos y producto terminado. Asegurar el cumplimiento de políticas, procedimientos internos y normas de seguridad vigentes.Perfil requerido: Secundario técnico completo: Técnico Mecánico, Químico o títulos afines. Contar con al menos 2 años de experiencia en posiciones similares, supervisando procesos productivos y equipos de trabajo.Se valorarán conocimientos en: Procesos productivos industriales Normas de calidad, seguridad y medio ambiente Manejo de stocks y control de costos Conocimientos mecánicos y eléctricos generales Manejo de Paquete OfficeBuscamos perfiles con fuerte orientación al trabajo en equipo, liderazgo, capacidad de negociación, flexibilidad horaria, compromiso y foco en la mejora continua.Condiciones: Jornada full time Modalidad presencial Posición efectiva Excelente oportunidad de desarrollo profesionalQuien reúna los requisitos solicitados, postularse indicando remuneración bruta pretendida.', 1, 'Belén de Escobar, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 09:27:10', '13-04-2026 09:57:57', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228691.html', '2026-04-15T07:05:56.000470');
