ull-time', '09-04-2026', '09-04-2026 19:03:08', '14-04-2026 08:18:16', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226148.html', '2026-04-15T07:05:56.001514');
