00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_945060_bum_v5125d27a.jpg', 1, 0, 3.28, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118231400.html', '2026-04-15T07:05:56.002478');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228138, 13457379, 'Gerente Comercial', 'YACOUB REAL ESTATE', 'Sumate como Gerente Comercial a Yacoub Real Estate 🚀¿Tenés experiencia liderando equipos de ventas y te motiva llevar un área comercial al siguiente nivel? Esta es tu oportunidad para crecer profesionalmente en una empresa en plena expansión.En Yacoub Real Estate vas a liderar la estrategia comercial, coordinar y desarrollar al equipo de asesores, hacer seguimiento de objetivos y performance, y optimizar los procesos de ventas para maximizar resultados. Vas a tener un rol clave en la toma de decisiones, trabajando directamente con la dirección para potenciar el crecimiento del negocio.Buscamos un perfil con sólida experiencia en liderazgo comercial, capacidad para gestionar equipos de alto rendimiento, visión estratégica y fuerte orientación a resultados. La experiencia en el rubro inmobiliario es un plus, pero no excluyente si contás con trayectoria comprobada liderando equipos comerciales en otros sectores.Lo que sí necesitás: habilidades de liderazgo, comunicación efectiva, capacidad de análisis, compromiso real y foco en el desarrollo de las personas y del negocio.El esquema es a comisión + fijo variable, con altos márgenes y posibilidad de generar ingresos acordes al desempeño del equipo. Además, vas a poder trabajar sobre desarrollos propios en pozo, con excelentes oportunidades comerciales.Funcionamos como una academia inmobiliaria, con foco en la formación continua 📚. Vas a contar con herramientas, procesos y soporte para potenciar tanto tu crecimiento como el del equipo que lideres. Dispondrás de nuestras oficinas sin costo y acceso total a la cartera de propiedades, junto con un flujo constante de clientes potenciales.Somos una empresa en fuerte crecimiento y buscamos un perfil que quiera asumir un rol protagonista en esta etapa. El ambiente es dinámico, colaborativo y orientado a resultados, con espacio real para proponer, innovar y generar impacto.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 12:42:07', '14-04-2026 12:42:07', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13457379_bum_v40775b45.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228138.html', '2026-04-15T07:05:56.002606');
