0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13208524_bum_v97869ef9.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228929.html', '2026-04-15T07:05:56.002756');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227327, 10095460, 'Gerente de Producción', 'Neo-Biz', 'Gerente de ProducciónImportante empresa agroindustrial del sur de Santa Fe, se encuentra en la búsqueda de un/a Gerente de Producción, con un rol clave en la gestión integral de las operaciones productivas, acompañando el crecimiento del negocio y asegurando eficiencia, calidad y cumplimiento de estándares. DesafíoLiderar el proceso productivo de punta a punta, desde la planificación y programación hasta la ejecución, garantizando el cumplimiento de los planes de producción, la optimización de recursos y la mejora continua, en un entorno industrial dinámico.Responsabilidades clave Definir y liderar la estrategia productiva, alineada al plan de negocio Asegurar la planificación y programación eficiente de la producción (PMP), optimizando capacidades, costos y tiempos Monitorear y gestionar indicadores clave (productividad, costos, calidad, servicio), impulsando decisiones basadas en datos Liderar la optimización de procesos industriales, promoviendo iniciativas de mejora continua y estandarización Gestionar el presupuesto del área y asegurar la eficiencia en el uso de recursos Garantizar el cumplimiento de estándares de calidad, seguridad y medio ambiente Articular con áreas clave (Logística, Mantenimiento, Calidad) para asegurar la eficiencia end-to-end Liderar y desarrollar equipos, consolidando una cultura de alto desempeño y mejora continua Participar en proyectos estratégicos de expansión, inversión y transformación operativaRequisitos Formación en Ingeniería (Industrial, Química, Mecánica o afines) Experiencia mínima de 5 a 8 años en posiciones de liderazgo en Producción/Operaciones Trayectoria liderando equipos y gestionando procesos industriales Visión estratégica combinada con fuerte capacidad de ejecución Se valorará experiencia en industrias agroquímicas, químicas, farmacéuticas o afines Perfil con fuerte orientación a resultados, mejora continua y toma de decisiones. Jornada laboral: Lunes a Viernes Full time.Todas las postulaciones serán tratadas con absoluta confidencialidad Requisitos:', 0, 'Santa Fe, Santa Fe', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:24:26', '10-04-2026 16:24:26', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10095460_bum_v946b7462.jpg', 1, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227327.html', '2026-04-15T07:05:56.002883');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226784, 981150, 'Gerente de tienda', 'Coppel S A', 'PROPÓSITO"Acompañarte en tus necesidades y deseos, acercándote un mundo de posibilidades para que mejores tu vida".VISIÓNSer la tienda omnicanal y de servicios financieros personales y digitales, favorita del mercado masivo, que ofrece una gran variedad de categorías de productos y servicios útiles, atractivos y accesibles, de marcas líderes, que atiende las necesidades, así como los deseos de los clientes.VALORESConfianzaResponsabilidadAtención y ServicioEficiencia y SencillezInnovación ¡En Coppel Arg tenemos un nuevo desafío para vos! Nos encontramos en la búsqueda de Gerentes de Tienda para sumarse a las siguientes zonas: Capital Federal, Zona Sur, Oeste y Norte.¿Cuáles son los desafíos del rol? Dirigir, entrenar y desarrollar el trabajo de las personas a cargo, con el fin de garantizar una atención de calidad a los clientes. Realizar el seguimiento y control de stock de la tienda. Controlar cotidianamente la imagen de la tienda. Cumplir con los objetivos establecidos para lograr los resultados necesarios para la rentabilidad del negocio. Manejo de relaciones sindicales. Reporta directamente al gerente zonal. Requisitos: Contar con experiencia previa en conducción de equipos y ventas, preferentemente en empresas de consumo masivo o retail. Movilidad propia (preferentemente) Disponibilidad horaria full-time (Con disponibilidad para realizar apertura y/o cierre de tienda). Estudiante avanzado/graduado de carreras provenientes de Administración, Comercialización, Marketing y/o afines (preferentemente). Convocamos a personas proactivas, organizadas y resolutivas, con gran iniciativa, compromiso y orientadas a la atención al cliente.Se valorarán habilidades de comunicación y establecimiento de relaciones a largo plazo. Beneficios Capacitación constante. OSDE para la persona contratada y grupo familiar. Día de cumpleaños off. Días libres para vos.y muchos', 0, 'Buenos Aires, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 12:31:29', '10-04-2026 12:31:29', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 6, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_981150_bum_ve0658e62.jpg', 0, 0, 3.77, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226784.html', '2026-04-15T07:05:56.002988');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118229755, NULL, 'Store Manager | Retail', 'Confidencial', 'Empresa líder en retail regional está en búsqueda de un Store Manager para liderar la operación integral de su tienda en CABA. Como Store Manager serás responsable de la gestión completa de la tienda, garantizando excelencia operativa, cumplimiento de métricas clave y liderazgo del equipo. Tu objetivo principal será asegurar una operación rápida, confiable y rentable. Buscamos una persona con habilidades de liderazgo y gestión de equipos, orientada a resultados y con capacidad de resolución de problemas. La oportunidad ofrece desarrollo profesional en un entorno dinámico y desafiante, liderando operaciones en una empresa líder del sector.Responsabilidades Supervisar apertura y cierre de tienda, garantizando responsables para cada turno Controlar el correcto ingreso de mercadería Validar orden y limpieza de instalaciones (estantes, heladeras, freezers, bodega) Asegurar disponibilidad operativa de equipos Gestionar requerimientos operativos y de mantenimiento Planificar dotación semanal de pickers según demanda Realizar reuniones 1:1 para feedback y evaluación de desempeño Administrar cambios de turno y horas adicionales Participar en procesos de selección de nuevos integrantes Gestionar ausentismo y faltas disciplinarias junto a RRHH Asegurar documentación al día (libretas sanitarias, cursos de manipulación de alimentos) Supervisar conteos cíclicos y saneos Monitorear rotación FIFO-FEFO Gestionar mermas conocidas y desconocidas Validar recepción de mercadería y gestionar surtido eficientemente Reportar resultados diarios y semanalesRequisitos Experiencia comprobable en gestión de equipos (Excluyente) Disponibilidad para trabajar en distintas franjas horarias (Excluyente) Disponibilidad para trabajar fines de semana (Excluyente) Experiencia en operaciones de alta rotación Conocimiento de sistemas de gestión de inventario (WMS) (Excluyente) Orientación a resultados y cumplimiento de KPIs Manejo de paquete Microsoft Office (Excluyente) Experiencia previa en retail: recepción de proveedores, interacción interáreas (Excluyente)', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 16:23:19', '14-04-2026 10:01:00', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118229755.html', '2026-04-15T07:05:56.003080');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118231290, 13476003, 'Responsable de ventas B2C, gerente comercial', 'WE ARE CRITERIUM', '🔎 En Criterium estamos buscando un/a Responsable de Ventas 💼 para sumarse al equipo de una empresa del rubro Fintech. 📍 Ubicación: Beccar, Zona Norte🕘 Horario: Lunes a viernes de 9 a 17 Hs. Modalidad: Presencial 🎯 Responsabilidades principales: – Diseñar e implementar estrategias de ventas alineadas con los objetivos – Optimizar la prospección de leads en conjunto con agencias y equipo de mkt – Coordinar acciones con mkt para mejorar la captación y conversión de clientes 🧠 Requisitos: – Experiencia comprobada de al menos 4 años en liderazgo de equipos de ventas – Conocimiento sólido en prospección de leads y marketing digital – Experiencia en mercados digitales y estrategias de crecimiento - Experiencia en gestion comercial de ventas de servicios/productos B2B. Esperamos tus postulación', 0, 'San Isidro, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 14:30:10', '14-04-2026 16:02:18', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 2, 0, 6, 35, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118231290.html', '2026-04-15T07:05:56.003162');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230676, 13430958, 'Gerente Comercial - Importante Cadena de Heladerías', 'Umano HR', '📢 Nos encontramos en la búsqueda de un/a Gerente Comercial para liderar la estrategia comercial de una importante cadena de Heladerías, con foco en crecimiento, rentabilidad y excelencia en la experiencia del cliente.Responsabilidades principales Definir y ejecutar el plan comercial anual, analizando mercado, competencia y tendencias para detectar oportunidades. Supervisar el cumplimiento de objetivos de ventas y rentabilidad, analizando KPIsclave y aplicando acciones correctivas. Asegurar estándares de atención, exhibición y servicio en tiendas, coordinando la correcta implementación de campañas y promociones. Garantizar la disponibilidad de productos mediante una coordinación eficiente con logística y abastecimiento. Liderar, motivar y desarrollar al equipo comercial, estableciendo metas claras y promoviendo la capacitación continua. Negociar con proveedores condiciones comerciales, descuentos y acciones promocionales, evaluando su desempeño y definiendo el mix de productos. Elaborar reportes de ventas, rentabilidad y performance para la Dirección,utilizando herramientas de análisis para la toma de decisiones. Impulsar iniciativas de digitalización, omnicanalidad y mejora continua, manteniéndose actualizado sobre tendencias del retail.Perfil buscado Experiencia previa en roles comerciales dentro del sector retail (excluyente). Capacidad analítica, orientación a resultados y visión estratégica. Liderazgo, habilidades de negociación y fuerte orientación al cliente. Proactividad, capacidad de organización y enfoque en mejora continua. Con disponibilidad para viajar. Horario Full Time. Modalidad presencial.Propuesta Incorporación a una empresa en crecimiento, con posibilidades de desarrollo. Rol estratégico con impacto directo en los resultados del negocio.Ofrecemos: Remuneración competitiva. Medicina prepaga para su grupo familiar. Gastos de movilidad.En caso de estar interesado envíanos tu CV a ref. Gte. Comercial.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 10:54:29', '14-04-2026 15:55:25', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13430958_bum_v6ea2e2d9.jpg', 0, 0, 3.64, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230676.html', '2026-04-15T07:05:56.003306');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118071297, 2205320, 'Gerente Comercial de Ventas. Zona Remedios de Escalada', 'Suministra', 'Importante empresa de refrigeración industrial se encuentra en la búsqueda de un Gerente Comercial de Ventas. Zona Remedios de EscaladaTareas a realizar:-Planificar, coordinar y liderar la estrategia comercial de la organización para cumplir con los objetivos de ventas, rentabilidad y crecimiento-Asegurar la gestión efectiva del equipo de ventas, promoviendo la mejora continua, el desarrollo del talento y la fidelización de clientes.-Generar reportes periódicos y análisis de mercado para la toma de decisiones.-Generar informes de ventas regulares y presentar los resultados al Gerente General junto con los planes de acción correspondientes.-Identificar oportunidades de mejora en los procesos de ventas y en el área.-Definir y ejecutar el plan estratégico de ventas para alcanzar los objetivos de la empresa.-Establecer metas y objetivos de ventas que acompañen el crecimiento de la empresa.-Participar en la definición de precios, promociones y políticas comerciales.-Analizar la competencia y ajustar las estrategias de ventas según sea necesario dentro de lo estipulado por la empresa.-Supervisión de tienda online: reclamos, ventas, pedidos. Realizar seguimiento de resultados e indicadores del área-Logística, crédito y compras: relevamiento de productos necesarios para reposición., comunicación directa con el área de Compras para planificación y gestión de acuerdos con Andreani (logística).-Gestionar, coordinar y acompañar al equipo de ventas en el cumplimiento de sus metas.-Evaluar el desempeño del equipo y proporcionar retroalimentación constructiva-Fomentar un ambiente de trabajo positivo y colaborativo.-Coordinar capacitaciones y desarrollo del equipo comercial.-Dar soporte al equipo de ventas ante situaciones que requieran su intervención.Horario laboral:Lunes a viernes de 09 a 18 hs / Sabados 09 a 13 hsPresencialRequisitos:-Secundario completo- Formación en carreras de Licenciatura en Comercialización, Administración de Empresas o afines-Experiencia 5 años mínimo en posiciones similares, liderando equipos comerciales y gestionando estrategias de ventas B2B y/o B2C. -Experiencia en Ventas Técnicas-Experiencia en comercializacion de electrodomesticos, piezas técnicas, refrigeración, etc-Experiencia en manejo de equipos de venta y desarrollo de estrategias de mercado-Experiencia en planeamiento comercial, análisis de indicadores de gestión-Manejo de Paquete Office , sistemas de gestión. CRM y herramientas de análisis comercial-Idioma ingles intermedio/avanzado-Residir en zonas aledañas-Disponibilidad para trabajar :Lunes a viernes de 09 a 18 hs / Sabados 09 a 13 hs (presencial)Se ofrecePuesto efectivo', 0, 'Remedios de Escalada, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 16:06:22', '09-04-2026 16:06:22', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2629, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2205320_bum_v84d969b6.jpg', 1, 0, 4.05, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118071297.html', '2026-04-15T07:05:56.003476');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179507, NULL, 'Gerente de Administración y Finanzas', 'Confidencial', '¿Te gustan los desafíos y te entusiasma desarrollar la gestión de un área?¡Esta es la oportunidad que estabas esperando!Estamos buscando un Gerente de Administración & Finanzas, quien tendrá el desafío de reorganizar la gestión del área en una empresa pyme, logrando definir e implementar una nueva estrategia del área con el fin de acompañar el crecimiento y desarrollo del negocio.¿Cuáles van a ser tus responsabilidades? Definir junto a la dirección e implementar la nueva estrategia del área. Planificar y dirigir la gestión financiera de la organización, asegurando el uso eficiente de los recursos de la misma. Liderar y gestionar el área y el equipo de Administración y Finanzas, promoviendo la eficiencia, el desarrollo profesional y el trabajo en equipo. Optimización y mejora continua de los procesos administrativos y financieros de la empresa. Asegurar el cumplimiento de las normativas administrativas y legales. Elaborar el presupuesto de la empresa y realizar un seguimiento del mismo, buscando identificar las oportunidades y los desvíos y tomar acción de manera oportuna. Analizar y gestionar el cash flow, asegurando la liquidez necesaria para la operación de la empresa. Realizar reportes del mismo, con el fin de acompañar a la Gerencia General de la empresa en la toma de decisiones estratégicas. Evaluar inversiones, costos y riesgos financieros, proponiendo alternativas que mejoren la rentabilidad. Asegurar el cumplimiento de obligaciones tributarias, laborales y legales. Desarrollar y mantener relaciones con proveedores y clientes clave. Colaborar con los departamentos de producción, calidad, y logística para apoyar la optimización de los rendimientos y la facturación de las diferentes áreas. Presentación de reportes y asesoramiento a la dirección de la empresa, aportando información clave para la planificación y el crecimiento del negocio.Requisitos Profesional graduado de las carreras de Administración de Empresas, Contador Público y/o afines. Marcada experiencia en posiciones similares en pymes manufactureras, preferentemente del sector de la industria alimenticia (no excluyente). Manejo de Excel, de Sistemas de Gestión, y de herramientas de análisis de datos. Será valorada la experiencia en TANGO y/o sistemas America. Posición Full Time CABA Capacidad Analítica y Estratégica, Habilidades de Liderazgo y de Comunicación, Capacidad de Planificación y Organización, Orientación a resultados, Proactividad y Resolución de Problemas, Flexibilidad, Confidencialidad en la información.', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '13-04-2026', '13-04-2026 12:54:14', '15-04-2026 02:20:06', '2026-04-13', NULL, NULL, '2026-04-13T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179507.html', '2026-04-15T07:05:56.003668');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179171, 650765, 'Gerente de Operaciones - Mar del Plata y Gran Buenos Aires', 'Soledad perez', 'Nos encontramos en la búsqueda de un/a Gerente de Operaciones – Region Mar del Plata y Gran Buenos Aires, una posición clave para liderar integralmente la operación y el desarrollo comercial de una región estratégica para la compañía.Buscamos un perfil con fuerte capacidad de liderazgo, visión de negocio, orientación a resultados y excelente manejo de relaciones con clientes, que pueda asegurar la calidad operativa, la rentabilidad de los servicios y la expansión sostenida de la zona. Misión del puestoGarantizar el cumplimiento de los objetivos operativos, comerciales y de rentabilidad en la región asignada, asegurando la calidad del servicio, la satisfacción del cliente y el desarrollo sostenido del negocio.Será el/la referente principal de la empresa en la zona, fortaleciendo vínculos con clientes actuales y promoviendo nuevas oportunidades comerciales. Principales responsabilidades Asegurar la correcta prestación de los servicios de limpieza, mantenimiento y demás operaciones en la región. Coordinar y supervisar al personal operativo y mandos medios, garantizando estándares de calidad, seguridad y productividad. Controlar el uso eficiente de los recursos humanos y materiales. Monitorear indicadores operativos y tomar acciones correctivas ante desvíos. Mantener y fortalecer la relación con los clientes actuales, identificando oportunidades de expansión horizontal y vertical. Desarrollar nuevas cuentas dentro de la región, alineadas a los objetivos comerciales de la compañía. Participar en procesos de cotización, relevamiento y armado de propuestas comerciales. Garantizar la rentabilidad de los contratos asignados. Liderar al equipo local, promoviendo el desarrollo, la motivación y el cumplimiento de objetivos. Supervisar el cumplimiento de políticas laborales y normativas de seguridad e higiene. Colaborar con el área administrativa en el control de ausentismo, altas/bajas y documentación. Representar a la empresa ante clientes, proveedores y entidades locales. Asegurar la correcta imagen corporativa en toda la región. Requisitos Formación preferente en Administración, Ingeniería Industrial o carreras afines. Experiencia mínima de 3 años en posiciones similares, idealmente en empresas de servicios, limpieza, mantenimiento, seguridad, hoteleria o facility management. Experiencia en gestión de operaciones tercerizadas. Manejo de personal operativo y de supervisión. Experiencia en gestión comercial y atención al cliente. Conocimiento en control de indicadores operativos y financieros. Manejo intermedio/avanzado de Excel y/o Google Sheets. Conocimiento y seguimiento de KPIs de gestión. Residencia en Mar del Plata o alrededores. Registro de conducir vigente. Referencias comprobables en la región. Competencias valoradas Liderazgo y trabajo en equipo Orientación al cliente y a resultados Visión comercial y detección de oportunidades Planificación y organización Comunicación efectiva y manejo de conflictos Capacidad analítica y toma de decisiones Proactividad y autonomía Negociación y excelente manejo interpersonal Modalidad Puesto efectivo | Tiempo completo Trabajo presencial Zona de cobertura: Mar del Plata, Costa Atlántica, Balcarce, Tandil y Bahía Blanca Requisitos:', 0, 'Mar del Plata, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 14:43:05', '08-04-2026 14:43:05', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2609, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179171.html', '2026-04-15T07:05:56.003841');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179341, 628677, 'Gerente de RRHH', 'B&B Consultores', '¡Atención San Nicolás y alrededores!¿Sos un líder con visión estratégica y amplia experiencia en relaciones laborales?Buscamos un Gerente de RRHH para liderar la profesionalización y ser el motor del cambio organizacional en una empresa referente del sector construcción en expansión. Ubicación: San Nicolás o localidades cercanas Horario: Jornada full time de lunes a viernesResponsabilidades: Cultura y clima: Ser embajador de los valores, impulsando el bienestar, la comunicación interna y actividades de integración. Transformación organizacional: Diseñar e implementar procesos que profesionalicen el área (estructuras, flujos de trabajo y mejora continua). Gestión sindical: Liderar las relaciones laborales, mediación de conflictos y cumplimiento normativo. Desarrollo de talento: Liderar planes de formación, inducción y atracción de talentos. Asesoría estratégica: Actuar como socio de la Dirección, Gerencia General y líderes de área en la toma de decisiones. Liderazgo de equipo: Coordinar equipo a su cargo. Requisitos: Formación: Lic. en Recursos Humanos, Relaciones Laborales, Administración o afines. Deseable Postgrado en Derecho Laboral o Relaciones Laborales. Experiencia: Mínimo de 4 a 6 años en posiciones similares, preferentemente en empresas constructoras o industriales. Conocimientos: manejo de convenio UOCRA, relaciones laborales y normativa laboral vigente. Habilidades: Capacidad de negociación, visión analítica, excelentes habilidades interpersonales y de organización. Beneficios Posición permanente con impacto real en los resultados y participación en decisiones estratégicas. Obra Social Prepaga: Swiss Medical (Plan para grupo familiar). Desarrollo: Posibilidades de crecimiento en un entorno de profesionalización constante. Ambiente: Excelente clima laboral y autonomía para proponer mejoras.', 0, 'San Nicolás de Los Arroyos, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:03:06', '10-04-2026 11:03:06', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_628677_bum_ve98665c.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179341.html', '2026-04-15T07:05:56.003951');
