INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178958, 664832, 'Encargada Enfermera para geriátrico', 'Residencia del Sol', 'Enfermera GeriatricaResumen del PuestoBuscamos una Enfermera para desempeñarse como encargada en Residencia geriátrica Proporcionar atención de enfermería integral a los residentes. Monitorear y evaluar el estado de salud de los pacientes. Administrar medicamentos y tratamientos según las indicaciones médicas. Colaborar con el equipo médico y otros profesionales de la salud. Encargarse de liderar el equipo de trabajoRequisitos Título de Enfermería y licencia profesional habilitada. Experiencia previa en geriatría o cuidado de adultos mayores será valorada. Conocimiento de las necesidades de salud específicas de la población geriátrica. Excelentes habilidades de comunicación interpersonal y empatía. Capacidad para trabajar en equipo y de forma autónoma. Compromiso con la atención centrada en el paciente.', 0, 'Castelar, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:08:17', '10-04-2026 12:10:51', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2654, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178958.html', '2026-04-15T07:05:56.004177');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118231066, NULL, 'Jefe de Calidad (ISO) y Control de Gestión.', 'Confidencial', 'Importante PyME metalúrgica de Zona Oeste incorpora Jefe de Calidad (ISO) y Control de Gestión.La posición tendrá como objetivo coordinar, implementar y sostener el Sistema de Gestión Integrado, asegurando el cumplimiento de normas, la mejora de procesos y la alineación entre la estrategia y la operación.Será responsable de la gestión de normas ISO 9001, 14001 y 45001, coordinando auditorías internas, externas y de clientes, así como el seguimiento de no conformidades, acciones correctivas y requisitos legales.En paralelo, liderará el proceso de Control de Gestión, participando en la definición y seguimiento de indicadores (KPI / CMI) y en la presentación de resultados a la dirección.Tendrá una participación activa en planta, trabajando junto a producción en el cumplimiento de estándares, análisis de desvíos y mejora continua de los procesos.Se trata de un rol transversal, con llegada a dirección, orientado a perfiles con capacidad de organización, mirada analítica y foco en la implementación práctica.Requisitos Universitario en curso / gradudado en carreras afines: Ingeniería Industrial, Ing. en Calidad, Administración de Empresas. (excluyente). También es deseable contar con base de escuela secundaria técnico. Experiencia en normas ISO 9001, 14001 y 45001 (excluyente) Experiencia en auditorías internas y externas Manejo de ERP / MRP (Bejerman, SAP u otros) (excluyente) Manejo avanzado de Excel Experiencia en control de gestión e indicadores (KPI / CMI) Experiencia mínima de 5 años en industria (excluyente) Experiencia en entornos productivos, con interacción con plantaOfrecemos Puesto efectivo en relación de dependencia Estabilidad laboral y posibilidades de desarrollo Prepaga Día libre por cumpleaños📍 Modalidad presencial – Zona Oeste (Morón) 🕘 Lunes a viernes de 08:00 a 17:00 hs', 1, 'Morón, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 13:09:01', '14-04-2026 13:47:55', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 16, 84, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118231066.html', '2026-04-15T07:05:56.004332');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118230700, 13411904, 'Baulerista / Gestión depósito - Distrito Arcos', 'Tisch S.R.L', 'MISHKA es una firma de zapatos y de marroquinería con énfasis en la creación handmade, fundada en Buenos Aires en 2001. A su colección de zapatos atemporales y de culto, suma una extensa línea de carteras y otra de indumentos llamada " Mishka Couture", que dialogan con el calzado.Desde su primer local situado en el barrio empedrado de Palermo, previamente conocido por su encanto bourgeois, hasta la actualidad con 25 Boutiques en Argentina, Chile y Uruguay, invita a una experiencia de compra integral a la usanza de las tiendas departamentales de antaño .Un enfoque y una búsqueda del estilo atemporal y avant-garde, definen el mundo que queremos crear y compartir continuamente en MISHKA. Buscamos incorporar un Baulerista para nuestra Boutique en Shopping Distrito Arcos que cuente con orientación a resultados, conocimiento en moda y facilidad para la organización.Condiciones: Disponibilidas horaria dentro de la franja de 10:00 a 22:00hs (mayor carga horaria por la mañana) Disponibilidad para Jornada Full Time.Entre sus principales tareas se encuentran: Recepción y expedición de mercadería Orden del depósito y control de stock Asistencia a las vendedoras del local Armado de pedidos Reposiciones en el salón de ventas Requisitos: Se valorara experiencia previa en ventas y reposición. Organización y planificación. Proactividad y dinamismo. Disponibilidad para trabar en Distrito Arcos. Beneficios Excelentes condiciones de contrataciónPosibilidades de crecimiento Salario básico Descuento en nuestras marcas Tasa preferencial en gimnasiosAviso de SeguridadCon el fin de proteger su información, le informamos que en ningún momento solicitaremos que ingrese datos personales a través de links, aplicaciones o bases de datos antes de su ingreso a la empresa.Asimismo, queremos recordarle que nuestras comunicaciones por correo electrónico siempre provendrán exclusivamente de direcciones con el dominio En ningún caso solicitaremos claves o contraseñas de uso personal.Recomendamos tener especial precaución al manejar su información personal, a fin de evitar caer en fraudes o robo de datos.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '14-04-2026', '14-04-2026 11:03:28', '14-04-2026 11:03:28', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118230700.html', '2026-04-15T07:05:56.004558');
