, 70, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_466770_bum_v7cd0e054.jpg', 1, 0, 3.92, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118161035.html', '2026-04-15T07:05:56.005052');
