026', '14-04-2026 14:14:30', '14-04-2026 14:28:51', '2026-04-14', NULL, NULL, '2026-04-14T00:00:00-03:00', NULL, NULL, 2, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118231254.html', '2026-04-15T07:05:56.005245');
